mapper.select:
SELECT total_point 
FROM member_point_tbl
WHERE member_id = #{memberId}

SELECT pointNo, memberId, pointChange, pointType, pointReason, createdDate FROM ( SELECT POINT_NO AS pointNo, MEMBER_ID AS memberId, POINT_CHANGE AS pointChange, POINT_TYPE AS pointType, POINT_REASON AS pointReason, DATE_FORMAT(CREATED_DATE, '%Y-%m-%d') AS createdDate, CREATED_DATE AS orderDate FROM point_tbl WHERE MEMBER_ID = #{memberId}
UNION ALL
SELECT CONTRIBUTION_NO AS pointNo, MEMBER_ID AS memberId, -CONTRIBUTED_POINT AS pointChange, 'USE' AS pointType, '나무 물주기' AS pointReason, DATE_FORMAT(CONTRIBUTED_AT, '%Y-%m-%d') AS createdDate, CONTRIBUTED_AT AS orderDate FROM region_contribution_tbl WHERE MEMBER_ID = #{memberId}
UNION ALL
SELECT D.DONATION_NO AS pointNo, D.MEMBER_ID AS memberId, -D.DONATION_POINT AS pointChange, 'DONATION' AS pointType, CONCAT(G.GROUP_NAME, '에 ', D.DONATION_POINT, 'P 기부') AS pointReason, DATE_FORMAT(D.DONATION_DATE, '%Y-%m-%d') AS createdDate, D.DONATION_DATE AS orderDate FROM point_donation D JOIN donation_group G ON D.GROUP_ID = G.GROUP_ID WHERE D.MEMBER_ID = #{memberId} AND D.DONATION_POINT > 0 ) AS history ORDER BY orderDate DESC, pointNo DESC
